type VXU_V04_TIMING struct {
	TQ1 TQ1   `hl7:"TQ1,required"`
	TQ2 []TQ2 `hl7:"TQ2"`
}

type VXU_V04_OBSERVATION struct {
	OBX OBX   `hl7:"OBX,required"`
	NTE []NTE `hl7:"NTE"`
}

type VXU_V04_ORDER struct {
	ORC         ORC                   `hl7:"ORC,required"`
	TIMING      []VXU_V04_TIMING      `hl7:"TIMING"`
	RXA         RXA                   `hl7:"RXA,required"`
	RXR         RXR                   `hl7:"RXR"`
	OBSERVATION []VXU_V04_OBSERVATION `hl7:"OBSERVATION"`
}

// VXU_V04 - Unsolicited Vaccination Record Update
// When a provider wishes to update the patient's vaccination record being held in a registry, he will transmit an unsolicited update of the record (a V04 trigger event).
type VXU_V04 struct {
	MSH       MSH                 `hl7:"MSH,required"`
	SFT       []SFT               `hl7:"SFT"`
	UAC       UAC                 `hl7:"UAC"`
	PID       PID                 `hl7:"PID,required"`
	PD1       PD1                 `hl7:"PD1"`
	NK1       []NK1               `hl7:"NK1"`
	PATIENT   VXU_V04_PATIENT     `hl7:"PATIENT"`
	GT1       []GT1               `hl7:"GT1"`
	INSURANCE []VXU_V04_INSURANCE `hl7:"INSURANCE"`
	ORDER     []VXU_V04_ORDER     `hl7:"ORDER"`
}

type VXX_V02_PATIENT struct {
	PID PID   `hl7:"PID,required"`
	NK1 []NK1 `hl7:"NK1"`
}

// VXX_V02 - Vaccination Record Query Returning Multiple PID Matches
// In response to a query for the definitive patient vaccination record, the registry holding the record will return it to the registry originating the query.
//
// Note: The original mode query, including QRD and QRF segments were retained for backward compatibility only as of v 2.4.
type VXX_V02 struct {
	MSH     MSH               `hl7:"MSH,required"`
	MSA     MSA               `hl7:"MSA,required"`
	SFT     []SFT             `hl7:"SFT"`
	UAC     UAC               `hl7:"UAC"`
	QRD     QRD               `hl7:"QRD,required"`
	QRF     QRF               `hl7:"QRF"`
	PATIENT []VXX_V02_PATIENT `hl7:"PATIENT,required"`
}
